#[test]
fn record_renewal_named_views_replay_origins_and_reject_owner_aliases() {
    let source = include_str!("../../tests/language/while_loops/record_borrow_renewal.spx");
    let ast = crate::check(source, Path::new("record-renewal-views.spx")).unwrap();
    let program = crate::hir::resolve(&ast).unwrap();
    crate::hir::validate(&program).unwrap();
    let index = program
        .functions
        .iter()
        .position(|f| f.id.as_str() == "matcher.run")
        .unwrap();
    let function = &program.functions[index];
    assert_eq!(build_plan(&program, function).unwrap(), function.loan_plan);
    let ResolvedExprKind::Block { statements, .. } = &function.body.kind else {
        panic!("run block")
    };
    let matcher = statements
        .iter()
        .find_map(|statement| match statement {
            ResolvedStatement::Let { binding, .. } if binding.name == "matcher" => {
                Some(binding.id.clone())
            }
            _ => None,
        })
        .unwrap();
    // Keep the whole named call operand intact. Admission must still recognize
    // the renewal shape, while independent loan rebuilding rejects its new
    // transitive origin even with the original attached proof untouched.
    let mut aliased = program.clone();
    {
        let ResolvedExprKind::Block { statements, .. } = &mut aliased.functions[index].body.kind
        else {
            panic!("run block")
        };
        let view = statements
            .iter_mut()
            .find_map(|statement| match statement {
                ResolvedStatement::Let { binding, value, .. } if binding.name == "input" => {
                    Some(value)
                }
                _ => None,
            })
            .unwrap();
        let ResolvedExprKind::BorrowPlace { place, .. } = &mut view.kind else {
            panic!("slice view")
        };
        place.root = matcher;
        place.projections = vec![crate::hir::PlaceProjection::Field(
            crate::hir::DeclarationId::new("matcher.storage"),
        )];
    }
    let ResolvedExprKind::Block { statements, .. } = &aliased.functions[index].body.kind else {
        panic!("run block")
    };
    let loop_body = statements
        .iter()
        .find_map(|statement| match statement {
            ResolvedStatement::While { body, .. } => Some(body),
            _ => None,
        })
        .unwrap();
    let ResolvedExprKind::Block { statements, .. } = &loop_body.kind else {
        panic!("loop block")
    };
    let (binding, call) = statements
        .iter()
        .find_map(|statement| match statement {
            ResolvedStatement::Assign { binding, value, .. } if binding.name == "matcher" => {
                Some((binding, value))
            }
            _ => None,
        })
        .unwrap();
    assert!(crate::hir::iterator_loop::is_record_owner_renewal(
        &aliased, binding, call
    ));
    let error = build_plan(&aliased, &aliased.functions[index]).unwrap_err();
    assert_eq!(error.code, "SPX-H006");
    assert_eq!(
        error.message,
        "move, mutation, or transfer overlaps an active shared loan"
    );
    assert_eq!(crate::hir::validate(&aliased).unwrap_err().code, "SPX-H006");

    let mut forged = program.clone();
    let loan = forged.functions[index]
        .loan_plan
        .loans
        .iter_mut()
        .find(|loan| matches!(loan.cause, LoanCause::BorrowedCall { .. }))
        .unwrap();
    loan.origin.root = function.params[0].id.clone();
    assert_eq!(crate::hir::validate(&forged).unwrap_err().code, "SPX-H006");

    let mut missing = program.clone();
    missing.functions[index].loan_plan = LoanPlan::empty_v1();
    assert_eq!(crate::hir::validate(&missing).unwrap_err().code, "SPX-H006");
}

#[test]
fn alias_projection_reconstruction_accounts_cumulative_growth_not_only_final_extent() {
    use crate::hir::DeclarationId;

    const LINKS: usize = 128;
    let mut aliases = BTreeMap::new();
    for index in 0..LINKS {
        aliases.insert(
            ValueId::intrinsic_parameter("root", index),
            Place {
                root: ValueId::intrinsic_parameter("root", index + 1),
                projections: vec![PlaceProjection::VariantField {
                    case: DeclarationId::new(format!("case.{index}")),
                    field: DeclarationId::new(format!("field.{index}")),
                }],
            },
        );
    }
    let initial = Place {
        root: ValueId::intrinsic_parameter("root", 0),
        projections: vec![PlaceProjection::Field(DeclarationId::new("initial"))],
    };
    let mut work = WorkCounter::new(MAX_LOAN_PLAN_WORK_V1);
    let (actual, observed) = crate::test_allocation_observer::measure(|| {
        origin::original(&aliases, initial, &mut work).unwrap()
    });
    assert!(!observed.invalid);
    assert_eq!(work.used, LINKS);
    assert_eq!(actual.root.as_str(), "root.param.128");
    assert_eq!(actual.projections.len(), LINKS + 1);
    for (position, projection) in actual.projections[..LINKS].iter().enumerate() {
        let index = LINKS - position - 1;
        assert_eq!(
            projection,
            &PlaceProjection::VariantField {
                case: DeclarationId::new(format!("case.{index}")),
                field: DeclarationId::new(format!("field.{index}")),
            }
        );
    }
    // Every link allocates a new projection vector containing its one prefix
    // plus the previous complete vector. The old vector is then dropped, but
    // those requests remain part of cumulative construction accounting.
    let projection_size = std::mem::size_of::<PlaceProjection>();
    let cumulative_vector_lower = (2..=LINKS + 1).sum::<usize>() * projection_size;
    assert!(observed.allocated >= cumulative_vector_lower);
    let largest_link_text = "case.127".len() + "field.127".len();
    let rejected_max_prefix_envelope =
        2 * (LINKS + 1) * (4 * 4 * projection_size + largest_link_text);
    assert!(cumulative_vector_lower > rejected_max_prefix_envelope);

    // These synthetic aliases exercise allocator behavior, not source or HIR
    // authority. Cyclic provenance remains an independently refused operation.
    aliases.insert(
        actual.root.clone(),
        Place {
            root: ValueId::intrinsic_parameter("root", 0),
            projections: Vec::new(),
        },
    );
    let mut work = WorkCounter::new(MAX_LOAN_PLAN_WORK_V1);
    assert_eq!(
        resolve_origin(
            &aliases,
            Place {
                root: ValueId::intrinsic_parameter("root", 0),
                projections: Vec::new(),
            },
            &mut work
        )
        .unwrap_err()
        .code,
        "SPX-H006"
    );
}

fn entry_stack_before(
    program: &ResolvedProgram,
    function: &ResolvedFunction,
) -> Result<LoanPlan, Diagnostic> {
    let lexical = crate::hir::lexical_exit::requires(function)?;
    if lexical {
        let owner = crate::hir::lexical_exit::owner(program, function)?;
        crate::hir::lexical_exit::validate_function(program, function, &owner)?;
    }
    has_own_root_candidate(program, function)
        .and_then(|candidate| {
            if candidate {
                build_cfg_plan(program, function)
            } else {
                let mut plan = LoanPlan::empty_v1();
                if lexical {
                    plan.schema = LOAN_PLAN_SCHEMA_V3;
                }
                Ok(plan)
            }
        })
        .map_err(|diagnostic| guidance::work_limit(diagnostic, function))
}

#[test]
fn entry_stack_isolation_keeps_whole_original_plans_diagnostics_and_debits() {
    let (owned, _) = super::boundary_tests::fixture(1);
    let scalar = crate::hir::resolve(
        &crate::check(
            "module entry.scalar; @id(\"entry.main\") fn main()->i64 {0}",
            "loan-entry-scalar.spx",
        )
        .unwrap(),
    )
    .unwrap();
    let lexical = crate::hir::resolve(
        &crate::check(
            r#"module cursor.mixed;
@id("cursor.probe") fn probe(n:i64)->i64 {
 let mut i=0;
 while i<n {i=i+1;if i==2 {continue;}else{0} if i==3 {break;}else{0} 0}
 if i>0 {return i+1;}else{0}
 return 0;
}
@id("main") fn main()->i64 {probe(4)}
"#,
            "loan-entry-lexical.spx",
        )
        .unwrap(),
    )
    .unwrap();
    fn compare(program: &ResolvedProgram, function: &ResolvedFunction) {
        let unlimited = crate::bounded_output::with_limit_usage_refusal(usize::MAX, || {
            entry_stack_before(program, function)
        });
        for limit in [usize::MAX, 0, unlimited.2.saturating_sub(1), unlimited.2] {
            let expected = crate::bounded_output::with_limit_usage_refusal(limit, || {
                entry_stack_before(program, function)
            })
            .0;
            let observe = |before: bool| {
                crate::bounded_output::with_limit_usage_refusal(limit, || {
                    crate::test_allocation_observer::measure(|| {
                        let actual = if before {
                            entry_stack_before(program, function)
                        } else {
                            build_plan(program, function)
                        };
                        assert_eq!(actual, expected);
                        drop(actual);
                    })
                })
            };
            let before = observe(true);
            let current = observe(false);
            assert!(!before.0 .1.invalid && !current.0 .1.invalid);
            assert_eq!(before.0 .1.live, 0);
            assert_eq!(current.0 .1.live, 0);
            assert_eq!(current, before);
        }
    }
    for program in [&scalar, &owned, &lexical] {
        for function in &program.functions {
            compare(program, function);
        }
    }
    let function = lexical
        .functions
        .iter()
        .find(|f| f.id.as_str() == "cursor.probe")
        .unwrap()
        .clone();
    let mut missing_owner = lexical.clone();
    missing_owner.functions.retain(|f| f.id != function.id);
    let error = entry_stack_before(&missing_owner, &function).unwrap_err();
    assert_eq!(error.code, "SPX-H006");
    assert_eq!(
        error.message,
        "unregistered lexical function requires an explicit authenticated execution context"
    );
    compare(&missing_owner, &function);
}

#[test]
fn entry_stack_isolation_restores_the_complete_original_producer_and_tests() {
    use sha2::{Digest, Sha256};
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let evidence = root.join("docs/evidence/loan-plan-entry-stack-v1");
    let records: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(evidence.join("sources.json")).unwrap())
            .unwrap();
    for record in records.as_array().unwrap() {
        let original =
            std::fs::read_to_string(evidence.join(record["archive"].as_str().unwrap())).unwrap();
        assert_eq!(
            format!(
                "{:x}",
                crate::digest_hex::LowerHex(Sha256::digest(original.as_bytes()))
            ),
            record["sha256"].as_str().unwrap()
        );
        let current = std::fs::read_to_string(root.join(record["path"].as_str().unwrap())).unwrap();
        let restore = |source: &str| -> Option<String> {
            let mut restored = source.to_owned();
            for edit in record["edits"].as_array().unwrap().iter().rev() {
                let new = edit["new"].as_str().unwrap();
                if restored.matches(new).count() != 1 {
                    return None;
                }
                restored = restored.replacen(new, edit["old"].as_str().unwrap(), 1);
            }
            Some(restored)
        };
        assert_eq!(restore(&current).as_deref(), Some(original.as_str()));
        assert_ne!(
            restore(&(current.clone() + "\n")).as_deref(),
            Some(original.as_str())
        );
        assert_ne!(
            restore(&current.replacen(&current[..1], "!", 1)).as_deref(),
            Some(original.as_str())
        );
    }
    let original = std::fs::read_to_string(evidence.join("loan_plan.rs.before.txt")).unwrap();
    let body = original
        .split("pub fn build_plan(\n")
        .nth(1)
        .unwrap()
        .split("\n/// Exact retained heap capacity")
        .next()
        .unwrap();
    let before = format!("fn entry_stack_before(\n{body}");
    let tests = std::fs::read_to_string(root.join("src/loan_plan/tests.rs")).unwrap();
    assert_eq!(
        tests.matches(&before).count(),
        1,
        "the complete original producer stays compiled"
    );
}

