            .or_else(|| (index == captures.len()).then_some(body.as_ref())),
        K::Block { statements, tail }
        | K::VecConstructor {
            statements, tail, ..
        } => {
            let mut offset = 0;
            for statement in statements {
                let count = statement.child_count();
