        | K::LiteralFormat { args, .. }
        | K::VecFieldRead { args, .. }
        | K::RowLoan { args, .. } => args.get(index),
        K::NativeRustImportCall(call) => call.args.get(index),
        K::HostCommandCall(call) => call.args.get(index),
